export function translate(locale: Locale, key: string, values: Values = {}) {
  const template = locale === "en" ? ENGLISH_EXTRA_2[key] ?? ENGLISH_EXTRA[key] ?? ENGLISH[key] ?? key : key;
  return template.replace(/\{\{(\w+)\}\}/gu, (_, name: string) => String(values[name] ?? ""));
}

export function localeFromRequest(request: Request): Locale {
  const cookie = request.headers.get("cookie")?.match(/(?:^|;\s*)brandycards-locale=(en|de)(?:;|$)/u)?.[1];
  if (cookie === "en" || cookie === "de") return cookie;
  return request.headers.get("accept-language")?.toLowerCase().startsWith("en") ? "en" : "de";
}
